argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$files=@('app/scripts/operator-lifecycle-r40.ps1','app/scripts/pause-all-r40.cmd','app/scripts/pause-browser-r40.cmd','app/scripts/resume-attach-r40.cmd','app/scripts/resume-managed-r40.cmd');
$git=(Get-Command git.exe -CommandType Application -ErrorAction Stop | Select-Object -First 1).Path;
$out=@();
foreach($f in $files){
  $headBlob=((@(& $git -C $repo rev-parse ('HEAD:'+$f)))-join '').Trim();
  $workBlob=((@(& $git -C $repo hash-object --path=$f (Join-Path $repo $f)))-join '').Trim();
  $rawSha=(Get-FileHash -LiteralPath (Join-Path $repo $f) -Algorithm SHA256).Hash.ToLowerInvariant();
  $out += [pscustomobject]@{file=$f;headBlob=$headBlob;workBlob=$workBlob;filteredEqual=($headBlob -eq $workBlob);rawSha256=$rawSha}
}
$status=@(& $git -C $repo status --short);
[pscustomobject]@{status=$status;files=$out}|ConvertTo-Json -Depth 5 -Compress
